#include <vector>
#include <algorithm>

class Solution {
public:
    long long maximumAlternatingSubarraySum(std::vector<int>& nums) {
        long long ans = nums[0];
        long long pos = nums[0];
        long long neg = -1e18;

        for (size_t i = 1; i < nums.size(); ++i) {
            long long x = nums[i];
            long long new_pos = std::max(x, neg + x);
            long long new_neg = pos - x;
            pos = new_pos;
            neg = new_neg;
            ans = std::max({ans, pos, neg});
        }
        return ans;
    }
};

class Solution {
    public long maximumAlternatingSubarraySum(int[] nums) {
        long ans = nums[0];
        long pos = nums[0];
        long neg = Long.MIN_VALUE / 2;

        for (int i = 1; i < nums.length; i++) {
            long x = nums[i];
            long newPos = Math.max(x, neg + x);
            long newNeg = pos - x;
            pos = newPos;
            neg = newNeg;
            ans = Math.max(ans, Math.max(pos, neg));
        }
        return ans;
    }
}

